import fsspec
fs = fsspec.filesystem('onedata')
root = 'icsa2027_data_20261101T090944Z'
# Use find instead of ls if available, or just loop through subdirs
all_files = []
def walk(path):
    for item in fs.ls(path):
        if fs.isdir(item):
            walk(item)
        else:
            all_files.append(item)

# fs.isdir might not be available. Let's check.
try:
    walk(root)
except Exception as e:
    print(f"Walk failed: {e}")

print(f"Total files found: {len(all_files)}")
if all_files:
    print(f"First 5: {all_files[:5]}")
    print(f"Last 5: {all_files[-5:]}")

import fsspec
fs = fsspec.filesystem('onedata')
root = 'icsa2027_data_20261101T090944Z'

# Manually walk and search for '2007'
def search_for_year(path, year):
    try:
        items = fs.ls(path)
        for item in items:
            if fs.isdir(item):
                search_for_year(item, year)
            elif year in item:
                print(f"Found: {item}")
    except Exception as e:
        pass

search_for_year(root, '2007')
